(ns fastmath.random.fitting-test
  (:require [fastmath.random.fitting :as sut]
            [fastmath.random :as r]
            [fastmath.random.distributions :as distr]
            [fastmath.core :as m]
            [clojure.edn :as edn]
            [clojure.java.io :as io]
            [clojure.test :as t]))

;; reference: R fitdistrplus::fitdist(method = "mle") and gofstat, generated by
;; utils/fastmath/dev/generate_fit_mle_reference.R
(def ^:private mle-reference
  (delay (edn/read-string (slurp (io/resource "random/fit_mle_reference.edn")))))

(defn- rel-error
  ^double [^double a ^double b]
  (m// (m/abs (m/- a b)) (m/max (m/abs b) 1.0e-300)))

(defn- close?
  [a b ^double tolerance]
  (m/<= (rel-error a b) tolerance))

;; a family which is a normal distribution with an extra integer parameter, only to test the engine:
;; a specification without estimators and with an :integer role parameter
(def ^:private int-normal-fit-spec
  {:params [{:name :mu :domain :real :role :location}
            {:name :sd :domain :positive :role :scale}
            {:name :k :domain :positive :role :integer}]
   :valid? #(distr/real-data-error % 2)})

;; registered only while the tests of this namespace run: other test namespaces enumerate the keys of `r/distribution`
(defn- int-normal
  ([_] (int-normal :fit-test-int-normal nil))
  ([_ {:keys [mu sd] :or {mu 0.0 sd 1.0}}]
   (let [d (r/normal {:mu mu :sd sd})]
     (distr/->distribution {:pdf (fn ^double [^double x] (r/pdf d x))
                            :lpdf (fn ^double [^double x] (r/lpdf d x))
                            :cdf (fn ^double [^double x] (r/cdf d x))
                            :icdf (fn ^double [^double p] (r/icdf d p))
                            :continuous? true
                            :name :fit-test-int-normal
                            :parameters [:mu :sd :k]
                            :lower-bound ##-Inf
                            :upper-bound ##Inf
                            :mean mu
                            :variance (m/sq sd)
                            :fit-spec int-normal-fit-spec}))))

(t/use-fixtures :once
  (fn [run-tests]
    (.addMethod ^clojure.lang.MultiFn r/distribution :fit-test-int-normal int-normal)
    (try (run-tests)
         (finally (remove-method r/distribution :fit-test-int-normal)))))

(def ^:private gamma-sample
  (r/->seq (r/distribution :gamma {:shape 2.5 :scale 1.7 :rng (r/rng :jdk 3)}) 400))

(defn- error-data
  [f]
  (try (f) nil
       (catch clojure.lang.ExceptionInfo e (ex-data e))))

(t/deftest fit-errors-test
  (t/testing "distributions which can't be fitted"
    (t/is (= :not-fittable (:type (error-data #(sut/fit :constant [1.0 2.0])))))
    (t/is (= :not-fittable (:type (error-data #(sut/fit :t [1.0 2.0 3.0]))))))
  (t/testing "data"
    (t/is (= :invalid-input (:type (error-data #(sut/fit :gamma [1.0 -2.0 3.0])))))
    (t/is (= :invalid-input (:type (error-data #(sut/fit :gamma [1.0])))))
    (t/is (= :invalid-input (:type (error-data #(sut/fit :normal [1.0 ##NaN 2.0])))))
    (t/is (= :invalid-input (:type (error-data #(sut/fit :beta [0.2 1.0 0.5]))))))
  (t/testing "options"
    (t/is (= :method (:property (error-data #(sut/fit :normal [1.0 2.0 3.0] {:method :ks})))))
    (t/is (= :fixed (:property (error-data #(sut/fit :normal [1.0 2.0 3.0] {:fixed {:nu 1.0}})))))
    (t/is (= :fixed (:property (error-data #(sut/fit :normal [1.0 2.0 3.0] {:fixed {:sd -1.0}})))))
    (t/is (= :fixed (:property (error-data #(sut/fit :normal [1.0 2.0 3.0] {:fixed {:mu "a"}})))))
    (t/is (= :fixed (:property (error-data #(sut/fit :normal [1.0 2.0 3.0] {:fixed {:mu 1.0 :sd 1.0}}))))))
  (t/testing "constant data have no normal distribution"
    (t/is (= :not-converged (:type (error-data #(sut/fit :normal [2.0 2.0 2.0])))))))

(t/deftest fit-mle-reference-test
  ;; closed form results (normal, log-normal, exponential) are compared to R to 1e-7: R fits the exponential
  ;; numerically (observed 7.8e-9); numeric results to 1e-3 on parameters (observed 5.2e-4 for cauchy, a flat
  ;; likelihood, otherwise 7.3e-5), 1e-7 on the information criteria (observed 4.2e-9) and 5e-3 on the
  ;; goodness-of-fit statistics (observed 2.8e-3), which follow the parameters
  (doseq [{:keys [distribution params data] :as c} @mle-reference
          closed-form? [true false]
          :let [res (sut/fit distribution data {:closed-form? closed-form?})
                exact? (and closed-form? (= :closed-form (:tier res)))
                ptol (if exact? 1.0e-7 1.0e-3)
                gtol (if exact? 1.0e-7 5.0e-3)]]
    (t/is (= distribution (r/distribution-id (:distribution res))) (str distribution))
    (t/is (:converged? res) (str distribution))
    (doseq [[nm v] params]
      (t/is (close? (get (:params res) nm) v ptol) (str distribution " " nm)))
    (doseq [k [:loglik :aic :aicc :bic]]
      (t/is (close? (get-in res [:stats k]) (get c k) 1.0e-7) (str distribution " " k)))
    (doseq [k [:ks :cvm :ad]]
      (t/is (close? (get-in res [:stats k]) (get c k) gtol) (str distribution " " k)))
    (t/is (= (:k c) (get-in res [:stats :k])))
    (t/is (= (:n c) (get-in res [:stats :n])))))

(t/deftest fit-tiers-test
  ;; observed difference between the numeric and the closed form parameters: 1.5e-8 (exponential)
  (doseq [k [:normal :exponential :log-normal]
          :let [data (case k
                       :normal (map #(- % 4.0) gamma-sample)
                       gamma-sample)
                cf (sut/fit k data)
                nm (sut/fit k data {:closed-form? false})]]
    (t/is (= :closed-form (:tier cf)))
    (t/is (= 0 (:iterations cf)))
    (t/is (= :numeric (:tier nm)))
    (t/is (pos? (:iterations nm)))
    (doseq [[p v] (:params cf)]
      (t/is (close? (get (:params nm) p) v 1.0e-7) (str k " " p)))))

(t/deftest fit-fixed-test
  (let [data (map #(- % 4.0) gamma-sample)
        mu 0.5
        sd (m/sqrt (m// (reduce + (map #(m/sq (m/- % mu)) data)) (count data)))
        res (sut/fit :normal data {:fixed {:mu mu}})]
    (t/testing "a fixed parameter is not fitted"
      (t/is (= :numeric (:tier res)))
      (t/is (= {:mu mu} (:fixed res)))
      (t/is (= mu (get-in res [:params :mu])))
      (t/is (close? (get-in res [:params :sd]) sd 1.0e-6))
      (t/is (= 1 (get-in res [:stats :k]))))
    (t/testing "the fitted distribution uses the fixed value"
      (t/is (m/delta-eq mu (r/mean (:distribution res))))))
  (t/testing "an integer parameter has to be fixed, the specification needs no estimators"
    (let [data (map #(- % 4.0) gamma-sample)
          err (error-data #(sut/fit :fit-test-int-normal data))
          res (sut/fit :fit-test-int-normal data {:fixed {:k 3}})
          ref (sut/fit :normal data)]
      (t/is (= :invalid-input (:type err)))
      (t/is (= :fixed (:property err)))
      (t/is (re-find #":k" (ex-message (try (sut/fit :fit-test-int-normal data)
                                            (catch clojure.lang.ExceptionInfo e e)))))
      (t/is (= 3.0 (get-in res [:params :k])))
      (t/is (= 2 (get-in res [:stats :k])))
      (t/is (close? (get-in res [:params :mu]) (get-in ref [:params :mu]) 1.0e-5))
      (t/is (close? (get-in res [:params :sd]) (get-in ref [:params :sd]) 1.0e-5)))))

(t/deftest fit-result-test
  (let [res (sut/fit :gamma gamma-sample)]
    (t/testing "keys"
      (t/is (= #{:distribution :params :method :tier :converged? :iterations :fixed :stats} (set (keys res))))
      (t/is (= #{:k :n :loglik :aic :aicc :bic :ks :cvm :ad} (set (keys (:stats res)))))
      (t/is (= :mle (:method res)))
      (t/is (= {} (:fixed res)))
      (t/is (= :gamma (r/distribution-id (:distribution res)))))
    (t/testing "the distribution has the fitted parameters"
      (t/is (m/delta-eq (r/mean (:distribution res))
                        (* (get-in res [:params :shape]) (get-in res [:params :scale])))))
    (t/testing "information criteria"
      (let [{:keys [k n loglik aic aicc bic]} (:stats res)]
        (t/is (= 2 k))
        (t/is (= 400 n))
        (t/is (m/delta-eq aic (- (* 2.0 k) (* 2.0 loglik))))
        (t/is (m/delta-eq bic (- (* k (m/log n)) (* 2.0 loglik))))
        (t/is (m/delta-eq aicc (+ aic (/ (* 2.0 k (inc k)) (- n k 1)))))
        (t/is (m/delta-eq loglik (r/log-likelihood (:distribution res) gamma-sample)))))
    (t/testing "AICc is undefined for n = k + 1"
      (t/is (= ##Inf (get-in (sut/fit :normal [1.0 2.0 4.0]) [:stats :aicc]))))))

(t/deftest fit-determinism-test
  (let [a (sut/fit :gamma gamma-sample)
        b (sut/fit :gamma gamma-sample)
        c (sut/fit :gamma gamma-sample {:rng (r/rng :jdk 99) :restarts 5})]
    (t/is (= (:params a) (:params b)))
    (t/is (= (:stats a) (:stats b)))
    (t/testing "another generator and more restarts reach the same optimum"
      (t/is (close? (get-in c [:stats :loglik]) (get-in a [:stats :loglik]) 1.0e-7)))))

(t/deftest negative-log-likelihood-test
  (let [nll #'sut/negative-log-likelihood
        xs (double-array [0.5 1.5 2.5])]
    (t/testing "minus the log likelihood"
      (t/is (m/delta-eq (- (r/log-likelihood (r/normal {:mu 1.0 :sd 2.0}) [0.5 1.5 2.5]))
                        ((nll :normal {} [:mu :sd] xs) [1.0 2.0]))))
    (t/testing "a failing or not finite evaluation is an infinite objective value"
      (t/is (= ##Inf ((nll :normal {} [:mu :sd] xs) [1.0 -2.0])))
      (t/is (= ##Inf ((nll :no-such-distribution {} [:mu :sd] xs) [1.0 2.0])))
      (t/is (= ##Inf ((nll :gamma {} [:shape :scale] (double-array [-1.0 2.0])) [2.0 1.0]))))))
